import type {
  ChainOfCommandChallenge, CommonDossierChallenge, ComplaintsDeskChallenge, DispatchBoxChallenge,
  MisfiledRecordsChallenge, MissingMinutesChallenge, PublicEnquiryChallenge, RedactedRecordsChallenge,
  SeatingCommitteeChallenge
} from '../types';

const records = (...labels: string[]) => labels.map((label,index)=>({id:`record-${index+1}`,label}));
const factCheckTerms = (): [string,string,string] => ['Four statements are accurate.','One statement contains a factual error.','Select the inaccurate statement and calibrate your confidence.'];
const complaint = (id:string,category:string,statements:[string,string,string,string,string],falseStatementIndex:number,explanation:string,source:string):ComplaintsDeskChallenge => ({id:`complaint-${id}`,roundType:'COMPLAINTS_DESK',category,prompt:`Identify the single inaccurate statement in this ${category.toLowerCase()} file.`,caseTitle:`${category} Register Complaint`,certifiedFacts:factCheckTerms(),statements,falseStatementIndex,explanation,source});
const seating = (id:string,category:string,order:[string,string,string,string,string],explanation:string,source:string):SeatingCommitteeChallenge => ({id:`seating-${id}`,roundType:'SEATING_COMMITTEE',category,prompt:`Arrange these ${category.toLowerCase()} records chronologically, earliest on the left.`,hearingTitle:`${category} Chronology Committee`,officials:[order[3],order[0],order[4],order[1],order[2]],clues:[`${order[0]} is the earliest record.`,`${order[1]} precedes ${order[2]}.`,`${order[2]} precedes ${order[3]}.`,`${order[4]} is the latest record.`],correctOrder:order,explanation,source});
type DispatchQuestion = DispatchBoxChallenge['questions'][number];
const q = (question:string,options:[string,string,string,string],correctIndex:number,explanation:string,source:string):DispatchQuestion => ({question,options,correctIndex,explanation,source});
const dispatch = (id:string,category:string,questions:DispatchBoxChallenge['questions']):DispatchBoxChallenge => ({id:`dispatch-${id}`,roundType:'DISPATCH_BOX',category,prompt:`Answer five short briefs from the ${category.toLowerCase()} register.`,questions});

